content:
Use one reusable environment module, but keep **dev and prod in separate Terraform states**. A single root state containing both `module.environment["dev"]` and `module.environment["prod"]` would not satisfy independent deployability.

## Layout

```text
modules/
  environment/
    main.tf
    variables.tf
    outputs.tf

live/
  main.tf
  variables.tf
  dev.tfvars
  prod.tfvars
```

## Root module

```hcl
# live/variables.tf
variable "environments" {
  description = "Normally contains exactly one environment per state."

  type = map(object({
    region = string

    cluster = object({
      instance_type = string
      desired_size  = number
    })

    database = object({
      instance_class    = string
      multi_az          = bool
      storage_encrypted = bool
    })

    assets = object({
      replication_enabled = bool
      replication_region  = optional(string)
    })

    https = object({
      mode            = string
      certificate_arn = string
    })

    db_secret_ciphertext = string
  }))

  validation {
    condition     = length(var.environments) == 1
    error_message = "Each Terraform state must manage exactly one environment."
  }

  sensitive = true
}
```

```hcl
# live/main.tf
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  backend "s3" {}
}

provider "aws" {
  region = values(var.environments)[0].region

  default_tags {
    tags = {
      Environment = keys(var.environments)[0]
      ManagedBy   = "Terraform"
    }
  }
}

# Static alias used by the module for prod bucket replication.
provider "aws" {
  alias  = "replica"
  region = "us-west-2"
}

module "environment" {
  for_each = var.environments
  source   = "../modules/environment"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  environment          = each.key
  region               = each.value.region
  cluster              = each.value.cluster
  database             = each.value.database
  assets               = each.value.assets
  https                = each.value.https
  db_secret_ciphertext = each.value.db_secret_ciphertext
}
```

Terraform cannot dynamically select provider aliases with `for_each`. Configuring the default provider for the single environment in the current state avoids that problem, while the static `aws.replica` alias handles `us-west-2` replication.

## Environment values

```hcl
# live/dev.tfvars
environments = {
  dev = {
    region = "us-east-1"

    cluster = {
      instance_type = "t3.medium"
      desired_size  = 2
    }

    database = {
      instance_class    = "db.t3.micro"
      multi_az          = false
      storage_encrypted = true
    }

    assets = {
      replication_enabled = false
      replication_region  = null
    }

    https = {
      mode            = "alb"
      certificate_arn = "arn:aws:acm:us-east-1:111111111111:certificate/DEV_CERT_ID"
    }

    # Supply through a SOPS-decrypted temporary var file or TF_VAR_*.
    # Do not commit plaintext.
    db_secret_ciphertext = "..."
  }
}
```

```hcl
# live/prod.tfvars
environments = {
  prod = {
    region = "us-east-2"

    cluster = {
      instance_type = "t3.large"
      desired_size  = 4
    }

    database = {
      instance_class    = "db.t3.medium"
      multi_az          = true
      storage_encrypted = true
    }

    assets = {
      replication_enabled = true
      replication_region  = "us-west-2"
    }

    https = {
      mode            = "cloudfront"
      certificate_arn = "arn:aws:acm:us-east-1:111111111111:certificate/PROD_CERT_ID"
    }

    db_secret_ciphertext = "..."
  }
}
```

Use distinct backend keys:

```bash
terraform init \
  -backend-config="bucket=my-terraform-state" \
  -backend-config="key=webapp/dev.tfstate" \
  -backend-config="region=us-east-1"

terraform plan -var-file=dev.tfvars
```

```bash
terraform init -reconfigure \
  -backend-config="bucket=my-terraform-state" \
  -backend-config="key=webapp/prod.tfstate" \
  -backend-config="region=us-east-1"

terraform plan -var-file=prod.tfvars
```

Workspaces can also be used, but distinct backend keys/accounts are generally harder to apply accidentally than workspace selection.

## Module contract

```hcl
# modules/environment/variables.tf
terraform {
  required_providers {
    aws = {
      source                = "hashicorp/aws"
      configuration_aliases = [aws.replica]
    }
  }
}

variable "environment" {
  type = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be dev or prod."
  }
}

variable "region" {
  type = string
}

variable "cluster" {
  type = object({
    instance_type = string
    desired_size  = number
  })
}

variable "database" {
  type = object({
    instance_class    = string
    multi_az          = bool
    storage_encrypted = bool
  })
}

variable "assets" {
  type = object({
    replication_enabled = bool
    replication_region  = optional(string)
  })
}

variable "https" {
  type = object({
    mode            = string
    certificate_arn = string
  })
}

variable "db_secret_ciphertext" {
  type      = string
  sensitive = true
}
```

The existing resource arguments should be moved into this module without changing their values. At minimum, preserve these invariants:

```hcl
# Representative arguments inside modules/environment/main.tf

resource "aws_eks_node_group" "application" {
  # Preserve existing cluster/subnet/role arguments.

  instance_types = [var.cluster.instance_type]

  scaling_config {
    desired_size = var.cluster.desired_size
    min_size     = var.cluster.desired_size
    max_size     = var.cluster.desired_size
  }
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_db_instance" "postgres" {
  # Preserve identifiers, engine versions, storage, network, and credentials.

  instance_class      = var.database.instance_class
  multi_az            = var.database.multi_az
  storage_encrypted   = var.database.storage_encrypted
  publicly_accessible = false
  deletion_protection = true
  backup_retention_period = 7
}
```

For prod, the module should create the replication IAM role/policy, destination bucket in `us-west-2`, destination versioning/encryption/public-access block, and `aws_s3_bucket_replication_configuration` only when `var.assets.replication_enabled` is true.

Do not turn an existing ALB into CloudFront during this refactor if zero-diff is required. First perform the address-only module move; make topology changes in a later reviewed plan.

## Zero-diff state moves

A move across a module boundary is safe when the resource type and provider configuration remain compatible. Every old address must map to its exact new address.

If the old shared configuration used suffixes such as:

```hcl
aws_eks_cluster.dev
aws_eks_cluster.prod
aws_s3_bucket.assets_dev
aws_s3_bucket.assets_prod
aws_db_instance.dev
aws_db_instance.prod
```

then the address migration is:

```hcl
# live/moved.tf

moved {
  from = aws_eks_cluster.dev
  to   = module.environment["dev"].aws_eks_cluster.this
}

moved {
  from = aws_eks_cluster.prod
  to   = module.environment["prod"].aws_eks_cluster.this
}

moved {
  from = aws_eks_node_group.dev
  to   = module.environment["dev"].aws_eks_node_group.application
}

moved {
  from = aws_eks_node_group.prod
  to   = module.environment["prod"].aws_eks_node_group.application
}

moved {
  from = aws_s3_bucket.assets_dev
  to   = module.environment["dev"].aws_s3_bucket.assets
}

moved {
  from = aws_s3_bucket.assets_prod
  to   = module.environment["prod"].aws_s3_bucket.assets
}

moved {
  from = aws_s3_bucket_versioning.assets_dev
  to   = module.environment["dev"].aws_s3_bucket_versioning.assets
}

moved {
  from = aws_s3_bucket_versioning.assets_prod
  to   = module.environment["prod"].aws_s3_bucket_versioning.assets
}

moved {
  from = aws_s3_bucket_server_side_encryption_configuration.assets_dev
  to   = module.environment["dev"].aws_s3_bucket_server_side_encryption_configuration.assets
}

moved {
  from = aws_s3_bucket_server_side_encryption_configuration.assets_prod
  to   = module.environment["prod"].aws_s3_bucket_server_side_encryption_configuration.assets
}

moved {
  from = aws_s3_bucket_public_access_block.assets_dev
  to   = module.environment["dev"].aws_s3_bucket_public_access_block.assets
}

moved {
  from = aws_s3_bucket_public_access_block.assets_prod
  to   = module.environment["prod"].aws_s3_bucket_public_access_block.assets
}

moved {
  from = aws_db_instance.dev
  to   = module.environment["dev"].aws_db_instance.postgres
}

moved {
  from = aws_db_instance.prod
  to   = module.environment["prod"].aws_db_instance.postgres
}
```

Also enumerate moves for all supporting resources: VPC/subnets, security groups, IAM roles and policy attachments, OIDC provider, ALB/CloudFront resources, ACM references, replication resources, random passwords, and secrets. Terraform has no wildcard module move; missing one produces a destroy/create proposal.

If the old resources are already in separate states and have unsuffixed addresses, each state gets an environment-specific move, for example in dev:

```hcl
moved {
  from = aws_db_instance.postgres
  to   = module.environment["dev"].aws_db_instance.postgres
}
```

and in prod:

```hcl
moved {
  from = aws_db_instance.postgres
  to   = module.environment["prod"].aws_db_instance.postgres
}
```

## Migration order

1. Pin the current Terraform and provider versions.
2. Make no argument, provider, naming, or topology changes.
3. Copy existing blocks verbatim into `modules/environment`.
4. Add the complete set of `moved` blocks.
5. Run `terraform plan -refresh=false`; it must report:

   ```text
   No changes. Your infrastructure matches the configuration.
   ```

6. Run a normal refreshed plan and resolve any pre-existing drift separately.
7. Apply the address-only migration.
8. If dev and prod currently share one state, split them into separate backend keys using backed-up state and explicit `terraform state mv -state/-state-out`; declarative `moved` blocks cannot split a state.
9. Only after the move is complete should security or topology changes be introduced.

A literal zero-diff guarantee cannot be made from generic names alone: the `moved` entries must use the actual addresses from `terraform state list`, and the module must preserve the exact resource arguments, provider aliases, `count`/`for_each` keys, and immutable identifiers.
